  cdelen = fast_expansion_sum_zeroelim(cdlen, cddet, elen, edet, cdedet);
  deterlen = fast_expansion_sum_zeroelim(ablen, abdet, cdelen, cdedet, deter);

  const double result_ = deter[deterlen - 1];
  ::litestl::alloc::release(scratch_);
  return result_;
